(5408663, 777574, 100393, '<td valign="top">Wow - you''ve really pulled this off - I predict a bimodal distribution. I''m in the upper peak! 9.</td>', 'Wow - you''ve really pulled this off - I predict a bimodal distribution. I''m in the upper peak! 9.', '2009-03-30 17:31:58.000000', NULL, 1),
(5408666, 777372, 100393, '<td valign="top">I really like this - great colours, unusual viewpoint. I hope this vision pays off for you. 8.</td>', 'I really like this - great colours, unusual viewpoint. I hope this vision pays off for you. 8.', '2009-03-30 17:33:08.000000', NULL, 1),
(5408667, 777599, 100393, '<td valign="top">Fantastic stuff - I''m sure that some people will think that you''ve applied a texture layer. I''m assuming you haven''t. 9.</td>', 'Fantastic stuff - I''m sure that some people will think that you''ve applied a texture layer. I''m assuming you haven''t. 9.', '2009-03-30 17:34:20.000000', NULL, 1),
