(5408830, 776735, 31637, '<td valign="top">Composition is strong, good sharpness, maybe a lower P.O.V would help trim down the empty space of the sky a bit.</td>', 'Composition is strong, good sharpness, maybe a lower P.O.V would help trim down the empty space of the sky a bit.', '2009-03-30 19:06:42.000000', NULL, 1),
(5408833, 776877, 31637, '<td valign="top">I think you should re-edit this and play with curves a bit more. Its exposed well but doesn''t Wow me.</td>', 'I think you should re-edit this and play with curves a bit more. Its exposed well but doesn''t Wow me.', '2009-03-30 19:08:14.000000', NULL, 1),
(5408855, 777413, 43774, '<td valign="top">There are two photos of this lighthouse in the challenge and I can''t decide which one I like the best so I''ve rated both of you a 9. I really like the exposure on the water here. Gorgeous colours in the sky too.</td>', 'There are two photos of this lighthouse in the challenge and I can''t decide which one I like the best so I''ve rated both of you a 9. I really like the exposure on the water here. Gorgeous colours in the sky too.', '2009-03-30 19:24:51.000000', NULL, 1),
(5408857, 776607, 43774, '<td valign="top">I like the vignette here and the light. Photo is a bit small, you can go to 720 pixels wide for a member challenge. An 8 from me.</td>', 'I like the vignette here and the light. Photo is a bit small, you can go to 720 pixels wide for a member challenge. An 8 from me.', '2009-03-30 19:26:13.000000', NULL, 1),
(5408858, 777342, 43774, '<td valign="top">Beautiful colours, nice big photo, great job.</td>', 'Beautiful colours, nice big photo, great job.', '2009-03-30 19:26:28.000000', NULL, 1),
