INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5408905, 777487, 43774, '<td valign="top">I like the perspective although it''s a bit dark in the middle. That''s a neat old fort and is good for the song title.</td>', 'I like the perspective although it''s a bit dark in the middle. That''s a neat old fort and is good for the song title.', '2009-03-30 19:48:57.000000', NULL, 1),
(5408906, 777488, 43774, '<td valign="top">Lovely action shot.</td>', 'Lovely action shot.', '2009-03-30 19:49:11.000000', NULL, 1),
(5408907, 776575, 43774, '<td valign="top">I like how your framed the photo, very clear, very good.</td>', 'I like how your framed the photo, very clear, very good.', '2009-03-30 19:49:27.000000', NULL, 1),
(5408909, 777381, 43774, '<td valign="top">Nice silhouette, good photo.</td>', 'Nice silhouette, good photo.', '2009-03-30 19:49:41.000000', NULL, 1),
(5408910, 777405, 100773, '<td valign="top">This would do nicely as a CD-cover for a metal band, but I think this is missing something to be a good photo. The location and the technical aspects if this is great, but I''m still missing something. Something that is more "damaged" perhaps? Just my thoughts. 6</td>', 'This would do nicely as a CD-cover for a metal band, but I think this is missing something to be a good photo. The location and the technical aspects if this is great, but I''m still missing something. Something that is more "damaged" perhaps? Just my thoughts. 6', '2009-03-30 19:49:45.000000', NULL, 1),
(5408912, 777205, 43774, '<td valign="top">What a beautiful old tree, a dramatic photo.</td>', 'What a beautiful old tree, a dramatic photo.', '2009-03-30 19:50:00.000000', NULL, 1),
(5408913, 777601, 43774, '<td valign="top">Good perspective, dramatic.</td>', 'Good perspective, dramatic.', '2009-03-30 19:50:23.000000', NULL, 1),
(5408914, 777164, 43774, '<td valign="top">Gorgeous scenery!! I just love those mountains.</td>', 'Gorgeous scenery!! I just love those mountains.', '2009-03-30 19:50:42.000000', NULL, 1),
(5408915, 777161, 43774, '<td valign="top">Nice gaze, I love the close crop/filling the frame.</td>', 'Nice gaze, I love the close crop/filling the frame.', '2009-03-30 19:51:01.000000', NULL, 1),
(5408916, 776944, 100773, '<td valign="top">I''m not any good with the technic my self, but HDR would probably help this photo. Mount the camera on a stand and shoot on more time to get more details in the sky. I think that wold''ve made it better. But, the idea is great and matches the beautifull song! 5</td>', 'I''m not any good with the technic my self, but HDR would probably help this photo. Mount the camera on a stand and shoot on more time to get more details in the sky. I think that wold''ve made it better. But, the idea is great and matches the beautifull song! 5', '2009-03-30 19:51:17.000000', NULL, 1),
(5408917, 775896, 43774, '<td valign="top">Did you add blur? It seems a bit artificial. But a lovely photo, really nice detail on the bird and nest.</td>', 'Did you add blur? It seems a bit artificial. But a lovely photo, really nice detail on the bird and nest.', '2009-03-30 19:51:57.000000', NULL, 1),
(5408919, 777315, 43774, '<td valign="top">Nice wave action, good job.</td>', 'Nice wave action, good job.', '2009-03-30 19:52:12.000000', NULL, 1),
(5408921, 777421, 43774, '<td valign="top">Love the look of the falling rain.</td>', 'Love the look of the falling rain.', '2009-03-30 19:52:30.000000', NULL, 1),
(5408924, 777523, 43774, '<td valign="top">The colours of the sunset reflected in the water is lovely.</td>', 'The colours of the sunset reflected in the water is lovely.', '2009-03-30 19:52:54.000000', NULL, 1),
(5408926, 777485, 43774, '<td valign="top">Good colour, nice capture of the drop. Not too fond of the background for some reason.</td>', 'Good colour, nice capture of the drop. Not too fond of the background for some reason.', '2009-03-30 19:53:30.000000', NULL, 1),
(5408929, 776879, 43774, '<td valign="top">I like the high key look and the red lips but feel the photo is too soft overall, especially where her hand blends into her face and her fingers blend into her arm (or so it seems).</td>', 'I like the high key look and the red lips but feel the photo is too soft overall, especially where her hand blends into her face and her fingers blend into her arm (or so it seems).', '2009-03-30 19:54:43.000000', NULL, 1),
(5408932, 777458, 100773, '<td valign="top">I was thinking something like this for "Paradise City" (Guns''n''roses), but decided on something else. It''s a brilliant shot that matches the title very good. I could say it lacks rock''n''roll feeling, but it doesn''t matter. Title vs photo, brilliant! Shoot one more for the postcard challenge! 7</td>', 'I was thinking something like this for "Paradise City" (Guns''n''roses), but decided on something else. It''s a brilliant shot that matches the title very good. I could say it lacks rock''n''roll feeling, but it doesn''t matter. Title vs photo, brilliant! Shoot one more for the postcard challenge! 7', '2009-03-30 19:56:45.000000', NULL, 1),
(5408935, 777467, 100773, '<td valign="top">Well, it''s a spinning wheel. Looks like you have moved some things during the exposure, or something like that. I found that disturbing, sorry. I think actually spinning the wheel during a 1s-2s exposure would make it better.</td>', 'Well, it''s a spinning wheel. Looks like you have moved some things during the exposure, or something like that. I found that disturbing, sorry. I think actually spinning the wheel during a 1s-2s exposure would make it better.', '2009-03-30 19:59:20.000000', NULL, 1),
(5408944, 777606, 100773, '<td valign="top">Original, funny and excellent work with the monkey and bananas. It really looks like they''re floating and flying in the sky. Bold attempt and a great job! 6</td>', 'Original, funny and excellent work with the monkey and bananas. It really looks like they''re floating and flying in the sky. Bold attempt and a great job! 6', '2009-03-30 20:02:45.000000', NULL, 1),
(5408948, 776134, 100773, '<td valign="top">To me it looks like the bumblebees texture somehow blends in with the background. I would like to see it sharper. Try adding a high pass filter (tip from an amateur) over a soft light layer if you have photoshop. Nevertheless, a beautifull photo matching the title. Giving the song a more positive vibe. Overall well done!</td>', 'To me it looks like the bumblebees texture somehow blends in with the background. I would like to see it sharper. Try adding a high pass filter (tip from an amateur) over a soft light layer if you have photoshop. Nevertheless, a beautifull photo matching the title. Giving the song a more positive vibe. Overall well done!', '2009-03-30 20:04:50.000000', NULL, 1),
(5408952, 777348, 100773, '<td valign="top">It certainly is a butterfly, won''t argue with you on that. In macro photographin it''s very easy to misplace the focus. Try to be aware of were you want your focus, and in this case I dare say you want it the wing closest to us, or preferably the head.</td>', 'It certainly is a butterfly, won''t argue with you on that. In macro photographin it''s very easy to misplace the focus. Try to be aware of were you want your focus, and in this case I dare say you want it the wing closest to us, or preferably the head.', '2009-03-30 20:07:24.000000', NULL, 1),
(5408959, 777369, 100773, '<td valign="top">She most certainly is! Photographing a girl/woman is hard work, and you have succeeded. The colors, depth of field, model and her makeup, it''s all very nice. Although, I would like to see the rest of the head. I also think that somewhat more excitement into this photo would help. As it is now, many might say it''s just a good portrait.</td>', 'She most certainly is! Photographing a girl/woman is hard work, and you have succeeded. The colors, depth of field, model and her makeup, it''s all very nice. Although, I would like to see the rest of the head. I also think that somewhat more excitement into this photo would help. As it is now, many might say it''s just a good portrait.', '2009-03-30 20:12:32.000000', NULL, 1),
(5408963, 777460, 77724, '<td valign="top">well somebody had to :)</td>', 'well somebody had to :)', '2009-03-30 20:14:57.000000', NULL, 1),
(5408964, 777579, 77724, '<td valign="top">Yeah another Freebird!!!</td>', 'Yeah another Freebird!!!', '2009-03-30 20:15:57.000000', NULL, 1),
(5408969, 776690, 100773, '<td valign="top">Black and white is also very challenging to do, and your attempt is nice and fits the theme nicely, but I think more could be done in the prossesing. It''s a great idea and a good performance, but you would need more to get the wanted "wow" factor. Read about black and white prossesing and what do to while shooting to make the prosessing easier and see if you might learn a few tricks. You''re on to something.</td>', 'Black and white is also very challenging to do, and your attempt is nice and fits the theme nicely, but I think more could be done in the prossesing. It''s a great idea and a good performance, but you would need more to get the wanted "wow" factor. Read about black and white prossesing and what do to while shooting to make the prosessing easier and see if you might learn a few tricks. You''re on to something.', '2009-03-30 20:19:09.000000', NULL, 1),
(5408970, 777284, 77724, '<td valign="top">abstract motion outake?  whether it is or not - nicely done.</td>', 'abstract motion outake?  whether it is or not - nicely done.', '2009-03-30 20:19:10.000000', NULL, 1),
(5408972, 777467, 102315, '<td valign="top">There are some elements that look a little mystical in this scene. I don''t know if they are intentional or not but I like em and it matches what the song is about. If I am thinking correctly about the song I believe from blood, sweat, and tears. "Wheel in the sky keeps on turnin"</td>', 'There are some elements that look a little mystical in this scene. I don''t know if they are intentional or not but I like em and it matches what the song is about. If I am thinking correctly about the song I believe from blood, sweat, and tears. "Wheel in the sky keeps on turnin"', '2009-03-30 20:19:49.000000', NULL, 1),
(5408975, 776408, 100773, '<td valign="top">Out of focus/in a low depth of field area gravel mixed with sand is something I struggle with every time I bring my camera to a beach or something like that. I don''t like the distorting effect it has, sorry. I also think your focus is in the bottom of the bottle, and I think it would be better if you have had the entire bottle in focus. Title is good and fits well with your photo, but I would like to see it reshot with more focus and less wet gravel.</td>', 'Out of focus/in a low depth of field area gravel mixed with sand is something I struggle with every time I bring my camera to a beach or something like that. I don''t like the distorting effect it has, sorry. I also think your focus is in the bottom of the bottle, and I think it would be better if you have had the entire bottle in focus. Title is good and fits well with your photo, but I would like to see it reshot with more focus and less wet gravel.', '2009-03-30 20:23:05.000000', NULL, 1),
(5408976, 777163, 102315, '<td valign="top">I love Soundgarden and think this is great depiction of the song title. I could see them using this on a CD booklet.</td>', 'I love Soundgarden and think this is great depiction of the song title. I could see them using this on a CD booklet.', '2009-03-30 20:23:20.000000', NULL, 1),
