(5409392, 777562, 15711, '<td valign="top">Oh wow - great idea.  Wish you could have included his tail too.</td>', 'Oh wow - great idea.  Wish you could have included his tail too.', '2009-03-30 23:59:51.000000', NULL, 1),
(5409393, 777552, 15711, '<td valign="top">This is beautiful. It''s as if they are dancing.</td>', 'This is beautiful. It''s as if they are dancing.', '2009-03-31 00:00:14.000000', NULL, 1),
