(5409539, 777554, 32108, '<td valign="top">Well this is my top pick, but in order to give some feedback the only negative comment I can make about this is it feels a little too crowded. Maybe some space to the left would have helped, what do I know.<br/> <br/>Well done, fantastic!</td>', 'Well this is my top pick, but in order to give some feedback the only negative comment I can make about this is it feels a little too crowded. Maybe some space to the left would have helped, what do I know. Well done, fantastic!', '2009-03-31 02:08:45.000000', NULL, 1),
(5409540, 777475, 32108, '<td valign="top">What a great feel to this, the exposure &amp; colouring is superb.</td>', 'What a great feel to this, the exposure & colouring is superb.', '2009-03-31 02:09:30.000000', NULL, 1),
(5409542, 777205, 32108, '<td valign="top">I could see this as their album cover, well done!</td>', 'I could see this as their album cover, well done!', '2009-03-31 02:10:08.000000', NULL, 1),
