(5409663, 777610, 57447, '<td valign="top">Good shot to fit challenge.  A little bright on the left though.</td>', 'Good shot to fit challenge.  A little bright on the left though.', '2009-03-31 07:45:23.000000', NULL, 1),
(5409676, 777552, 100773, '<td valign="top">Interesting photo! Double Vision is represented quite well, especially from the swan to the left. The one to the right is more like an abstract, white thing floating on what apears to be water, so I think it would be enough with only the one to the left. My oppinion that is.</td>', 'Interesting photo! Double Vision is represented quite well, especially from the swan to the left. The one to the right is more like an abstract, white thing floating on what apears to be water, so I think it would be enough with only the one to the left. My oppinion that is.', '2009-03-31 08:15:07.000000', NULL, 1),
(5409677, 776122, 100773, '<td valign="top">Well, yeah... I would like to see more focus on the one biting the apple instead of two nicely shot apples with their reflection.</td>', 'Well, yeah... I would like to see more focus on the one biting the apple instead of two nicely shot apples with their reflection.', '2009-03-31 08:16:53.000000', NULL, 1),
(5409678, 777315, 100773, '<td valign="top">It''s a good photo, and it fits the theme as it is now, but there''s nothing special here. For instance, a man/woman sitting on the beach gazing into the horizon would really help. Then you would get more 6 and 7 rather than 4 and 5.</td>', 'It''s a good photo, and it fits the theme as it is now, but there''s nothing special here. For instance, a man/woman sitting on the beach gazing into the horizon would really help. Then you would get more 6 and 7 rather than 4 and 5.', '2009-03-31 08:20:23.000000', NULL, 1),
