INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5412825, 776816, 46314, '<td valign="top">Very funny expression you caught.</td>', 'Very funny expression you caught.', '2009-04-01 16:56:58.000000', NULL, 1),
(5412828, 777420, 46314, '<td valign="top">This just makes me laugh. Of all the song titles in the world, you were so drawn to this one that you went to all that effort to set up this shot... Did you shoot this on the final day of submissions by any chance? :-)</td>', 'This just makes me laugh. Of all the song titles in the world, you were so drawn to this one that you went to all that effort to set up this shot... Did you shoot this on the final day of submissions by any chance? :-)', '2009-04-01 16:59:42.000000', NULL, 1),
(5412830, 776651, 46314, '<td valign="top">Great shot. Very well planned and executed.</td>', 'Great shot. Very well planned and executed.', '2009-04-01 17:00:08.000000', NULL, 1),
(5412835, 777418, 46314, '<td valign="top">Nice shot. Somehow it feels to me like I''d want the wheelchair on the left side of the frame... Just think it might be more balanced that way.</td>', 'Nice shot. Somehow it feels to me like I''d want the wheelchair on the left side of the frame... Just think it might be more balanced that way.', '2009-04-01 17:01:29.000000', NULL, 1),
(5412836, 777525, 46314, '<td valign="top">Cool shot. If it had been a crocodile on a rock, it would have been perfect.</td>', 'Cool shot. If it had been a crocodile on a rock, it would have been perfect.', '2009-04-01 17:02:06.000000', NULL, 1),
(5412839, 777487, 46314, '<td valign="top">I like this shot, but I think I might have liked it more if the strong, imposing shape in the foreground hadn''t been in such strong shadows. My eye seems to want to veer to the left where the sunshine is.</td>', 'I like this shot, but I think I might have liked it more if the strong, imposing shape in the foreground hadn''t been in such strong shadows. My eye seems to want to veer to the left where the sunshine is.', '2009-04-01 17:03:22.000000', NULL, 1),
(5412841, 777616, 46314, '<td valign="top">Nice zoom.</td>', 'Nice zoom.', '2009-04-01 17:03:38.000000', NULL, 1),
(5412843, 777064, 46314, '<td valign="top">Lol. This is funny. It''s not my favourite photo ever, but I love the way you set it up.</td>', 'Lol. This is funny. It''s not my favourite photo ever, but I love the way you set it up.', '2009-04-01 17:04:13.000000', NULL, 1),
(5412848, 777477, 46314, '<td valign="top">Got a Cartier-Bresson feel in the style and processing, but this image doesn''t really speak to me.</td>', 'Got a Cartier-Bresson feel in the style and processing, but this image doesn''t really speak to me.', '2009-04-01 17:05:17.000000', NULL, 1),
(5412851, 776408, 46314, '<td valign="top">Needed something more to make it a really striking image: better lighting, or more interesting composition perhaps.</td>', 'Needed something more to make it a really striking image: better lighting, or more interesting composition perhaps.', '2009-04-01 17:07:04.000000', NULL, 1),
(5412857, 777111, 46314, '<td valign="top">It''s a nice image, and I like the subdued colours you processed. It''s probably because of where I come from, but seagulls make me think of the seaside, and the seaside makes me think of sunshine, so it kinda ruins the winter feel for me.</td>', 'It''s a nice image, and I like the subdued colours you processed. It''s probably because of where I come from, but seagulls make me think of the seaside, and the seaside makes me think of sunshine, so it kinda ruins the winter feel for me.', '2009-04-01 17:09:07.000000', NULL, 1),
(5412861, 777467, 46314, '<td valign="top">Are those reflections from a window?</td>', 'Are those reflections from a window?', '2009-04-01 17:10:34.000000', NULL, 1),
(5412863, 776760, 46314, '<td valign="top">Or ''A Winter''s Tale''...</td>', 'Or ''A Winter''s Tale''...', '2009-04-01 17:11:18.000000', NULL, 1),
(5412865, 777195, 46314, '<td valign="top">Nice shot. I like the silhouettes. Maybe if you''d isolated the couple, or even the fisherman, it would have been an even stronger image.</td>', 'Nice shot. I like the silhouettes. Maybe if you''d isolated the couple, or even the fisherman, it would have been an even stronger image.', '2009-04-01 17:12:24.000000', NULL, 1),
(5412867, 776607, 46314, '<td valign="top">Nice shot. Very symbolic.</td>', 'Nice shot. Very symbolic.', '2009-04-01 17:12:53.000000', NULL, 1),
(5412879, 776429, 46314, '<td valign="top">I like this shot. A few minor adjustments and it could be a truly stunning work.</td>', 'I like this shot. A few minor adjustments and it could be a truly stunning work.', '2009-04-01 17:17:36.000000', NULL, 1),
(5412881, 777595, 46314, '<td valign="top">Great shot.</td>', 'Great shot.', '2009-04-01 17:17:57.000000', NULL, 1),
(5412882, 777601, 46314, '<td valign="top">Good image. Great balance and tones.</td>', 'Good image. Great balance and tones.', '2009-04-01 17:18:17.000000', NULL, 1),
(5412884, 776735, 46314, '<td valign="top">Not a bad shot, just not a great shot.</td>', 'Not a bad shot, just not a great shot.', '2009-04-01 17:18:39.000000', NULL, 1),
(5412889, 777116, 46314, '<td valign="top">NIce image. I like the circular framing.</td>', 'NIce image. I like the circular framing.', '2009-04-01 17:19:02.000000', NULL, 1),
(5412892, 777574, 46314, '<td valign="top">Interesting shot. Pinhole? Holga? Either way, I like the tones and shapes.</td>', 'Interesting shot. Pinhole? Holga? Either way, I like the tones and shapes.', '2009-04-01 17:19:34.000000', NULL, 1),
(5412894, 777164, 46314, '<td valign="top">Nice shot. Wish I was there...</td>', 'Nice shot. Wish I was there...', '2009-04-01 17:19:55.000000', NULL, 1),
(5412899, 777350, 46314, '<td valign="top">I like the sense of space in this image.</td>', 'I like the sense of space in this image.', '2009-04-01 17:20:26.000000', NULL, 1),
(5412903, 777374, 46314, '<td valign="top">Lol. Funny image.</td>', 'Lol. Funny image.', '2009-04-01 17:20:49.000000', NULL, 1),
(5412907, 777208, 46314, '<td valign="top">Could have been used in the ''Remember those?'' challenge...</td>', 'Could have been used in the ''Remember those?'' challenge...', '2009-04-01 17:21:18.000000', NULL, 1),
(5412909, 777598, 46314, '<td valign="top">Interesting idea. I think it might have worked better without the coloured strips at the top - so that you just have the coloured reflection in the glasses.</td>', 'Interesting idea. I think it might have worked better without the coloured strips at the top - so that you just have the coloured reflection in the glasses.', '2009-04-01 17:22:10.000000', NULL, 1),
(5412911, 777507, 46314, '<td valign="top">Sad looking seagull...</td>', 'Sad looking seagull...', '2009-04-01 17:22:29.000000', NULL, 1),
(5412912, 777165, 46314, '<td valign="top">Great portrait. I love the lighting and processing.</td>', 'Great portrait. I love the lighting and processing.', '2009-04-01 17:23:02.000000', NULL, 1),
(5412913, 776879, 46314, '<td valign="top">Very well shot and processed. Looks almost porcelain, not human.</td>', 'Very well shot and processed. Looks almost porcelain, not human.', '2009-04-01 17:23:47.000000', NULL, 1),
(5412915, 776670, 46314, '<td valign="top">Or, if you''d saturated the colour a little more... "Red, Red, Wine" :-)</td>', 'Or, if you''d saturated the colour a little more... "Red, Red, Wine" :-)', '2009-04-01 17:24:23.000000', NULL, 1),
