(5412931, 777331, 46314, '<td valign="top">Very humourous. Nicely shot.</td>', 'Very humourous. Nicely shot.', '2009-04-01 17:27:54.000000', NULL, 1),
(5412932, 777521, 46314, '<td valign="top">Very funny tie-in to the title. Great shot though - brilliant sharpness.</td>', 'Very funny tie-in to the title. Great shot though - brilliant sharpness.', '2009-04-01 17:28:22.000000', NULL, 1),
(5412933, 776636, 46314, '<td valign="top">Nice macro. Good colours and composition.</td>', 'Nice macro. Good colours and composition.', '2009-04-01 17:28:27.000000', NULL, 1),
(5412939, 777372, 46314, '<td valign="top">Clever way to represent the title.</td>', 'Clever way to represent the title.', '2009-04-01 17:28:57.000000', NULL, 1),
