(5412943, 777161, 46314, '<td valign="top">Great shot. Love the tight crop and the colours.</td>', 'Great shot. Love the tight crop and the colours.', '2009-04-01 17:31:04.000000', NULL, 1),
(5412950, 777381, 91282, '<td valign="top">Awesome. This is my favorite so far in the challenge (and not just because I''m a huge Van Halen fan!). Hope to see this ribbon.</td>', 'Awesome. This is my favorite so far in the challenge (and not just because I''m a huge Van Halen fan!). Hope to see this ribbon.', '2009-04-01 17:32:58.000000', NULL, 1),
