(5415445, 777562, 30454, '<td valign="top">One of three 10s in the challenge. So my pick for the ribbon. Excellent details, and perfect exposure.</td>', 'One of three 10s in the challenge. So my pick for the ribbon. Excellent details, and perfect exposure.', '2009-04-02 18:13:56.000000', NULL, 1),
(5415448, 776690, 30454, '<td valign="top">WOW, excellent leading line composition. I like the BW treatment. One of my high score, good luck.</td>', 'WOW, excellent leading line composition. I like the BW treatment. One of my high score, good luck.', '2009-04-02 18:14:42.000000', NULL, 1),
(5415451, 777195, 30454, '<td valign="top">Excellent composition, stunning colors. Oned of my high score, good luck.</td>', 'Excellent composition, stunning colors. Oned of my high score, good luck.', '2009-04-02 18:15:35.000000', NULL, 1),
(5415452, 777523, 30454, '<td valign="top">Oh, WOW. What a beautiful capture. I like the POV, movement, and perfect exposure here. One of my high score, good luck.</td>', 'Oh, WOW. What a beautiful capture. I like the POV, movement, and perfect exposure here. One of my high score, good luck.', '2009-04-02 18:16:28.000000', NULL, 1),
(5415461, 777509, 30454, '<td valign="top">Excellent portrait, nice setup and lighting. I would like  to see the eyes more sharper. Still one of my top score, good luck.</td>', 'Excellent portrait, nice setup and lighting. I would like  to see the eyes more sharper. Still one of my top score, good luck.', '2009-04-02 18:22:00.000000', NULL, 1),
(5415567, 777163, 2158, '<td valign="top">I kind of like this photo, but think it would work better in high contrast black and white, possibly leaving the colour in the eye.</td>', 'I kind of like this photo, but think it would work better in high contrast black and white, possibly leaving the colour in the eye.', '2009-04-02 19:15:57.000000', NULL, 1),
(5415618, 777606, 104010, '<td valign="top">I''d think the bananas would be a bit more ripe in heaven.</td>', 'I''d think the bananas would be a bit more ripe in heaven.', '2009-04-02 19:50:48.000000', NULL, 1),
