(5418957, 777405, 9411, '<td valign="top">Suits the song well. Love the mystery. Really like an image where interpretation is left to the viewer. I keep getting flashes of Auschwitz. 10</td>', 'Suits the song well. Love the mystery. Really like an image where interpretation is left to the viewer. I keep getting flashes of Auschwitz. 10', '2009-04-04 20:48:24.000000', NULL, 1),
(5418960, 776879, 9411, '<td valign="top">I don''t know the song, but this is a stunning image. Concept, execution,crop, desaturation all perfect.  10</td>', 'I don''t know the song, but this is a stunning image. Concept, execution,crop, desaturation all perfect.  10', '2009-04-04 20:50:06.000000', NULL, 1),
(5418961, 776816, 9411, '<td valign="top">Was just listening to this. Really fine image almost abstract but very evident what it is. 9</td>', 'Was just listening to this. Really fine image almost abstract but very evident what it is. 9', '2009-04-04 20:50:58.000000', NULL, 1),
