(5430696, 777475, 97954, '<td valign="top">congrats on top 10!  Love the lighting and the mood the color of the light sets here.</td>', 'congrats on top 10!  Love the lighting and the mood the color of the light sets here.', '2009-04-10 14:07:51.000000', NULL, 0),
(5431947, 777380, 81362, '<td valign="top">Wonderful capture of joy in (and perhaps stimulated by) a striking environment. I saw several children spontaneously dancing and jumping happliy in similar setttings last week. To me, the setting is just as important as the dancer. Having a shot that does not include a face allows the viewer much lattitude in creating internal stories about the image. I was unable to vote in this challenge due to travel in red rock country of southwest Utah -- but the trip helped me appreciate your entry. Riff on "Rolling Stones" a welcome extra touch.</td>', 'Wonderful capture of joy in (and perhaps stimulated by) a striking environment. I saw several children spontaneously dancing and jumping happliy in similar setttings last week. To me, the setting is just as important as the dancer. Having a shot that does not include a face allows the viewer much lattitude in creating internal stories about the image. I was unable to vote in this challenge due to travel in red rock country of southwest Utah -- but the trip helped me appreciate your entry. Riff on "Rolling Stones" a welcome extra touch.', '2009-04-11 12:15:03.000000', NULL, 0),
(5432277, 777578, 48697, '<td valign="top">Your Wolf shots are rocking man! Congrats on your successful  series of these beautiful animals!</td>', 'Your Wolf shots are rocking man! Congrats on your successful  series of these beautiful animals!', '2009-04-11 18:36:09.000000', NULL, 0),
(5432854, 776075, 27133, '<td valign="top">Awesome work sweetie...congrats.</td>', 'Awesome work sweetie...congrats.', '2009-04-12 08:14:34.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5433476, 777485, 102315, '<td valign="top">I can''t believe this only scored a 5.8 and didn''t even make the top ten. This shot was everything this challenge was about! Again wonderful work!</td>', 'I can''t believe this only scored a 5.8 and didn''t even make the top ten. This shot was everything this challenge was about! Again wonderful work!', '2009-04-12 20:16:14.000000', NULL, 0),
(5435082, 777537, 30982, '<td valign="top">This one definitely made me hear the song - and I didn''t even see the guy checking his watch until you pointed it out.  I can be kinda dense that way.  Very appropriate shot to go with your title!</td>', 'This one definitely made me hear the song - and I didn''t even see the guy checking his watch until you pointed it out.  I can be kinda dense that way.  Very appropriate shot to go with your title!', '2009-04-13 15:16:57.000000', NULL, 0),
(5435113, 777212, 68769, '<td valign="top">Just watched-listened on <a href="//www.youtube.com/watch?v=ZgMEPk6fvpg" rel="nofollow" target="_blank">Youtube</a> strange they named it the way they did. But it does fit the song quite well..</td>', 'Just watched-listened on Youtube strange they named it the way they did. But it does fit the song quite well..', '2009-04-13 15:44:14.000000', NULL, 0),
